use vstd::prelude::*;
use vstd::seq::Seq;

verus! {

/// Linear search: return the first index of `e` in `a`,
/// or `a.len()` if `e` does not occur.
/// 
/// Ensures:
/// 1. 0 ≤ res ≤ |a|
/// 2. either res == |a| (not found)
///    or a[res] == e
/// 3. ∀ j < res, a[j] ≠ e
fn linear_search(a: &Vec<i32>, e: i32) -> (res: usize)
    ensures
        // Bound
        res <= Seq::from_vec(a).len(),
        // If in‐bounds, we found the element
        (res == Seq::from_vec(a).len() || Seq::from_vec(a).index(res) == e),
        // No earlier occurrence
        forall |j: nat| j < res ==> Seq::from_vec(a).index(j) != e,
{
    // Convert the input Vec to an immutable sequence for specification
    let seq: Seq<i32> = Seq::from_vec(a);
    let n: nat = seq.len();

    // i is our scanning index
    let mut i: usize = 0;

    // Scan until we hit the end or find e
    while i < n
        invariant
            // 0 ≤ i ≤ n
            i <= n,
            // No occurrence of e in [0, i)
            forall |j: nat| j < i ==> seq.index(j) != e,
        decreases n - i,
    {
        if seq.index(i) == e {
            // found it: break out with i pointing at the first match
            break;
        }
        i += 1;
    }

    // Return the index i
    let res = i;
    res
}

} // verus!

